In jax ~0.6.2 the following PR by @superbobry was merged 0e7c96a
which removed the PyTreeDef::MakeFromNodeDataAndChildren method from PyTreeDef.
it turns out that I was using this method to (de)serialise PyTreeDefs objects to Json with a pair of method as follows
def serialize_PyTreeDef(obj):
    return {
        "node_data": obj.node_data(),
        "children": obj.children(),
    }


def deserialize_PyTreeDef(obj):
    return jax.tree_util.PyTreeDef.make_from_node_data_and_children(
        jax.tree_util.default_registry, obj["node_data"], obj["children"]
    )
this was, as far as I understood, the only way to 'serialise and deserialise' a PyTreeDef object containing custom nodes, because the protobof path works only for builtins. (Technically there is also __getstate__ and __setstate__ for pickle, but I cannot use pickle and I could not figure out a way to use __setstate__ without pickle)
I noticed only now because I was stuck on jax 0.5 and updated only recently.
Is there a replacement for that method? or more in general, if I have the node data and children can I build a PyTreeDef?
(If you are curious why I'm doing this, it is because I was serialising a flax.nnx model's graphdef to json, which keeps some PyTreeDefs inside cc @cgarciae )

Description
I extended the implementation of RMSNorm in the FFI tutorial to run on GPU, following the “FFI calls on a GPU” section. When calling the CUDA version (rms_norm_cuda), the program results in a segmentation fault, whereas the CPU version (rms_norm_cpu) executes correctly.
Below is the adapted code implementing both rms_norm_cpu and rms_norm_cuda:
#include <functional>
#include <numeric>
#include <utility>

#include "xla/ffi/api/c_api.h"
#include "xla/ffi/api/ffi.h"
#include "nanobind/nanobind.h"
#include "cuda_runtime_api.h"

namespace ffi = xla::ffi;
namespace nb = nanobind;

#include <cmath>
#include <cstdint>

float ComputeRmsNorm(float eps, int64_t size, const float *x, float *y) {
  float sm = 0.0f;
  for (int64_t n = 0; n < size; ++n) {
    sm += x[n] * x[n];
  }
  float scale = 1.0f / std::sqrt(sm / float(size) + eps);
  for (int64_t n = 0; n < size; ++n) {
    y[n] = x[n] * scale;
  }
  return scale;
}

template <ffi::DataType T>
std::pair<int64_t, int64_t> GetDims(const ffi::Buffer<T> &buffer) {
  auto dims = buffer.dimensions();
  if (dims.size() == 0) {
    return std::make_pair(0, 0);
  }
  return std::make_pair(buffer.element_count(), dims.back());
}

ffi::Error RmsNormImplCpu(float eps,
                       ffi::Buffer<ffi::F32> x,
                       ffi::ResultBuffer<ffi::F32> y) {
  auto [totalSize, lastDim] = GetDims(x);
  if (lastDim == 0) {
    return ffi::Error::InvalidArgument("RmsNorm input must be an array");
  }
  for (int64_t n = 0; n < totalSize; n += lastDim) {
    ComputeRmsNorm(eps, lastDim, &(x.typed_data()[n]), &(y->typed_data()[n]));
  }
  return ffi::Error::Success();
}

ffi::Error RmsNormImplCuda(cudaStream_t stream, float eps,
                       ffi::Buffer<ffi::F32> x,
                       ffi::ResultBuffer<ffi::F32> y) {
  auto [totalSize, lastDim] = GetDims(x);
  if (lastDim == 0) {
    return ffi::Error::InvalidArgument("RmsNorm input must be an array");
  }
  for (int64_t n = 0; n < totalSize; n += lastDim) {
    ComputeRmsNorm(eps, lastDim, &(x.typed_data()[n]), &(y->typed_data()[n]));
  }
  return ffi::Error::Success();
}

// Wrap `RmsNormImpl` and specify the interface to XLA.
XLA_FFI_DEFINE_HANDLER(
    RmsNormCpu, RmsNormImplCpu,
    ffi::Ffi::Bind()
        .Attr<float>("eps")
        .Arg<ffi::Buffer<ffi::F32>>()  // x
        .Ret<ffi::Buffer<ffi::F32>>()  // y
);

XLA_FFI_DEFINE_HANDLER(
    RmsNormCuda, RmsNormImplCuda,
    ffi::Ffi::Bind()
        .Ctx<ffi::PlatformStream<cudaStream_t>>()
        .Attr<float>("eps")
        .Arg<ffi::Buffer<ffi::F32>>()  // x
        .Ret<ffi::Buffer<ffi::F32>>()  // y
);

NB_MODULE(rms_norm_module, m) {
  m.def("rms_norm_cuda", []() { return nb::capsule(reinterpret_cast<void *>(RmsNormCuda)); });
  m.def("rms_norm_cpu", []() { return nb::capsule(reinterpret_cast<void *>(RmsNormCpu)); });  
}
On the Python side, the functions are imported as:
from rms_norm_example import rms_norm_module
import jax
jax.ffi.register_ffi_target("rms_norm_cuda", rms_norm_module.rms_norm_cuda(), platform="CUDA")
jax.ffi.register_ffi_target("rms_norm_cpu", rms_norm_module.rms_norm_cpu(), platform="cpu")

It seems that updating the function signature and handler definition is not sufficient; something may be missing in the tutorial.
System info (python version, jaxlib version, accelerator, etc.)
Python 3.10.12
JAX/JAXLIB 0.6.2
NVIDIA A100 80GB
CUDA 12.6

It honestly took some time to decide whether this is even jax's responsibility, but some recent additions to the cpython documentation (not yet on docs.python.org, but copied below) does describe that destructors need to work in the presence of yet unhandled errors (more alternatives also at Python Specification for DLPack). The dlpack capsule destructor clears error set by PyCapsule_GetPointer if the name changes, but this would also affect an existing error.
I would love to give a minimal reproducer here of what happens, but the only time I can get an observable error is via c-extension module functions, and even there the error message really depends on when exactly it gets deallocated (as a "local" variable, or as an "argument"). The interpreter seems to guard against this in regular python functions and all builtins that I have checked. But, here is a Cython-based reproducer:
# jax_dlpack.py
import traceback
from jax import numpy as jnp
from dummy_cython_mod import dummy_cfunc1, dummy_cfunc2

try:
  x = jnp.zeros(1)
  dummy_cfunc1(x.__dlpack__())
except Exception:
  traceback.print_exc()

try:
  x = jnp.zeros(1)
  dummy_cfunc2([x.__dlpack__()])
except Exception:
  traceback.print_exc()
Traceback (most recent call last):
  File "jax_dlpack.py", line 7, in <module>
    dummy_cfunc1(x.__dlpack__())
    ~~~~~~~~~~~~^^^^^^^^^^^^^^^^
SystemError: error return without exception set
Traceback (most recent call last):
  File "jax_dlpack.py", line 13, in <module>
    dummy_cfunc2([x.__dlpack__()])
    ~~~~~~~~~~~~^^^^^^^^^^^^^^^^^^
SystemError: <cyfunction dummy_cfunc2 at 0x7a22f7cbc400> returned NULL without setting an exception

# dummy_cython_mod.pyx
from cpython cimport PyCapsule_SetName

def dummy_cfunc1(pack):
  # ignore the fact that this would already be a memory leak even without any other errors.
  PyCapsule_SetName(pack, b'used_dltensor')
  assert False

def dummy_cfunc2(packs):
  pack = packs.pop()
  PyCapsule_SetName(pack, b'used_dltensor')
  assert False
